 const rounds=input.ep05Rounds??(legacyStage==="ROUND1_PLAY"?([{roundId:"round1",pairIds:input.pair.slice(0,2),preparationCompleted:false,timerStarted:false,timerFinished:false,taskOutcome:"",dialogueProgress:{ready:0,eye:0,after:0},completionStatus:"inProgress",generatedClipIds:[]} as Ep05Round]):[]);
