function readKcSmsArchive(p:P):KcSmsArchiveRow[]{
 const rows:KcSmsArchiveRow[]=[];
 for(let night=1;night<=12;night++){
  const key=night===1?"day1":`episode${night}`;const raw=p.gameUi?.[key];if(typeof raw!=="string")continue;
  let saved:Record<string,unknown>;try{saved=JSON.parse(raw) as Record<string,unknown>}catch{continue;}
  const delivered=night===1?saved.smsSent===true:(night<=3?saved.smsSent===true:saved.sent===true);if(!delivered)continue;
  const deliveries:{senderId:GuestId;recipientId:GuestId}[]=[];
  if(night===1&&saved.smsIds&&typeof saved.smsIds==="object"){
   for(const itemId of Object.values(saved.smsIds as Record<string,unknown>)){if(typeof itemId!=="string")continue;const item=p.items.find(x=>x.id===itemId);const sender=String(item?.meta?.senderId??"") as GuestId;const recipient=String(item?.meta?.recipient??"") as GuestId;if(all.includes(sender)&&all.includes(recipient))deliveries.push({senderId:sender,recipientId:recipient});}
  }else{
   const choices=(night<=3?saved.smsTargets:saved.sms) as Record<string,unknown>|undefined;
   if(choices)for(const [senderValue,recipientValue] of Object.entries(choices)){const sender=senderValue as GuestId;const recipient=String(recipientValue) as GuestId;if(all.includes(sender)&&all.includes(recipient))deliveries.push({senderId:sender,recipientId:recipient});}
  }
  if(deliveries.length!==5)continue;
  rows.push({episode:night,outcome:deriveKcSmsOutcome(kcSmsFlagsFromDeliveries(deliveries))});
 }
 return rows;
}
